export const BODY: string = "\n<p>تحويل صورة إلى PDF من أكثر أعمال الملفات فائدة في الحياة اليومية. صورة واحدة أو مستند كامل يصبح ملفًا واحدًا جاهزًا للإرسال.</p>\n<p>العملية كلها تستغرق دقائق، حتى لمستند طويل. ترفع الصور وترتبها وتختار الإعدادات وتنزّل المستند.</p>\n<p>يمر هذا الدليل بكل خطوة بالترتيب، حتى يخرج أول PDF لك نظيفًا واحترافيًا.</p>\n<h2 id=\"gather-your-images\">الخطوة 0: اجمع وجهّز صورك</h2>\n<p>الخطوة 0: اجمع صورة وجهّزها. اختر الصور التي تريدها في المستند، وتأكد من أنها واضحة وبالاتجاه الصحيح.</p>\n<p>إذا كانت الصور من مسح ضوئي، فتأكد من أنها غير مقلوبة. تدوير الصور بعد التوليد أصعب بكثير من تدويرها قبله.</p>\n<h2 id=\"open-the-tool\">الخطوة 1: افتح أداة الصورة إلى PDF</h2>\n<p>افتح <a href=\"/ar/tahwil-as-suwar-ila-pdf/\">أداة تحويل الصور إلى PDF</a> في متصفحك. تعمل الأداة بالكامل على جهازك دون رفع الصور إلى أي خادم.</p>\n<p>لا حاجة إلى حساب أو تثبيت. افتح الصفحة وابدأ فورًا، وستبقى صورك خاصة طوال العملية.</p>\n<h2 id=\"upload-and-order\">الخطوة 2: ارفع الصور وحدد الترتيب</h2>\n<p>ارفع الصور وحدد ترتيبها: أسقط كل الصور في منطقة الرفع، ثم اسحبها في القائمة إلى الترتيب الصحيح.</p>\n<p>الترتيب في القائمة هو ترتيب الصفحات في PDF. تحقق منه مرتين قبل المتابعة.</p>\n<h2 id=\"choose-page-size\">الخطوة 3: اختر حجم الصفحة</h2>\n<p>اختر حجم الصفحة: A4 للمستندات الرسمية، وحرف لأمريكا الشمالية، وملاءمة الصورة للصور الفوتوغرافية.</p>\n<p>إذا كنت غير متأكد، فاختر A4. إنه المعيار في معظم الدول ويُقبل في معظم النماذج.</p>\n<h2 id=\"set-orientation\">الخطوة 4: حدد الاتجاه والموضع</h2>\n<p>حدد الاتجاه والموضع: عمودي للمستندات والصور الطويلة، وأفقي للصور العريضة. الاتجاه التلقائي يختار الأنسب لكل صورة.</p>\n<p>اختر الملاءمة لعرض الصورة كاملة، أو التغطية لملء الصفحة. للمستندات استخدم الملاءمة حتى لا يُقص نص مهم.</p>\n<h2 id=\"margins-and-quality\">الخطوة 5: حدد الهوامش والجودة</h2>\n<p>حدد الهوامش والجودة: هوامش صغيرة للمستندات الرسمية، ولا هوامش للصور بملء الصفحة. جودة 85 مناسبة لمعظم الاستخدامات.</p>\n<p>للجودة القصوى اختر 95، وللمشاركة عبر البريد اختر جودة متوازنة لتقليل حجم الملف.</p>\n<h2 id=\"preview-and-check\">الخطوة 6: راجع كل شيء قبل التوليد</h2>\n<p>راجع كل شيء قبل التوليد: ترتيب الصفحات وحجمها واتجاهها وهوامشها. المعاينة تظهر كيف سيبدو المستند النهائي.</p>\n<p>إذا لاحظت خطأ، فأصلحه الآن. التصحيح قبل التوليد أسهل بكثير من التصحيح بعده.</p>\n<h2 id=\"generate-and-download\">الخطوة 7: ولّد ونزّل ملف PDF</h2>\n<p>ولّد ونزّل ملف PDF: اضغط زر التوليد وانتظر حتى ينتهي، ثم نزّل الملف واحفظه باسم واضح.</p>\n<p>افتح الملف المنزّل وتأكد من أنه صحيح: كل الصفحات موجودة وبالترتيب الصحيح والجودة جيدة.</p>\n<ol>\n<li>ارفع صورك ورتبها.</li>\n<li>اختر حجم الصفحة والاتجاه.</li>\n<li>حدد الهوامش والجودة.</li>\n<li>ولّد PDF ونزّله.</li>\n</ol>\n<h2 id=\"converting-a-single-photo\">كيف تحوّل صورة واحدة إلى PDF؟</h2>\n<p>لتحويل صورة واحدة إلى PDF، اتبع الخطوات نفسها بصورة واحدة. صورة واحدة تصبح صفحة واحدة في المستند.</p>\n<p>هذا مفيد للنماذج التي تطلب PDF بدل صورة. صورة واحدة كملف PDF تُقبل في أماكن ترفض ملفات الصور.</p>\n<h2 id=\"converting-scans\">كيف تحوّل مستندات ممسوحة؟</h2>\n<p>لتحويل مستندات ممسوحة، امسح بدقة 200 نقطة في البوصة أو أكثر، ورتب الصفحات بالترتيب الصحيح قبل الرفع.</p>\n<p>استخدم حجم A4 وهوامش صغيرة وجودة عالية للمستندات الممسوحة. النص الواضح هو الأولوية الأولى.</p>\n<h2 id=\"fixing-common-problems\">كيف تحل المشاكل الشائعة؟</h2>\n<p>لحل المشاكل الشائعة، افحص السبب أولًا. ملف PDF كبير يعني جودة عالية جدًا، وصفحات مقلوبة تعني صورًا مرفوعة بالاتجاه الخاطئ.</p>\n<p>أصلح المشكلة في المصدر قبل إعادة التوليد. إعادة التوليد من صور مصححة أسرع من محاولة إصلاح PDF نفسه.</p>\n<h2 id=\"mobile-tips\">نصائح للهواتف والأجهزة اللوحية</h2>\n<p>نصائح للهواتف والأجهزة اللوحية: افتح الأداة في المتصفح وارفع الصور من معرضك. التحويل يحدث على جهازك.</p>\n<p>على الشاشات الصغيرة، تحقق من ترتيب الصور بعناية. السحب والإفلات على الهاتف يحتاج إلى دقة أكبر.</p>\n<h2 id=\"receipts-for-expenses\">كيف تحوّل إيصالات للمصروفات؟</h2>\n<p>لتحويل إيصالات للمصروفات، امسح الإيصالات بوضوح ورتبها حسب التاريخ قبل التحويل. ملف PDF واحد لكل شهر يسهّل المحاسبة.</p>\n<p>استخدم جودة متوازنة للإيصالات: النص يجب أن يبقى مقروءًا، لكن الملف يجب أن يبقى صغيرًا للإرسال.</p>\n<h2 id=\"portfolio-pdf\">كيف تبني PDF محفظة؟</h2>\n<p>لبناء PDF محفظة، اختر أفضل أعمالك ورتبها بترتيب يعرض مهاراتك. ابدأ بأقوى عمل وانتهِ بعمل قوي أيضًا.</p>\n<p>استخدم حجمًا كبيرًا للصفحات وجودة عالية. المحفظة تمثل عملك، والجودة العالية تترك انطباعًا أقوى.</p>\n<h2 id=\"photos-and-scans-together\">كيف تجمع الصور والمسح الضوئي في PDF واحد؟</h2>\n<p>للجمع بين الصور والمسح الضوئي في PDF واحد، ارفعها معًا ورتبها بالترتيب المنطقي: المستندات أولًا ثم الصور، أو حسب ما يناسب محتواك.</p>\n<p>استخدم إعدادات موحدة لكل الصفحات. الاتساق يجعل المستند يبدو احترافيًا ومنظمًا.</p>\n<h2 id=\"sending-the-pdf\">كيف ترسل PDF إلى شخص آخر؟</h2>\n<p>لإرسال PDF إلى شخص آخر، أرسله عبر البريد أو خدمة مشاركة ملفات. اذكر في الرسالة ما يحتويه الملف وعدد صفحاته.</p>\n<p>إذا كان الملف كبيرًا جدًا للبريد، فاخفض الجودة وأعد التوليد، أو ارفعه إلى خدمة سحابية وشارك الرابط.</p>\n<h2 id=\"id-photos-applications\">كيف تحوّل صور مستندات الهوية للطلبات؟</h2>\n<p>لتحويل صور مستندات الهوية للطلبات، امسحها بوضوح وحوّلها إلى PDF بحجم A4 وجودة عالية. تأكد من أن النص والأرقام مقروءة.</p>\n<p>تحقق من متطلبات البوابة قبل الإرسال: بعض البوابات تطلب PDF وبعضها يطلب صورًا. وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-tahwil-as-suwar-ila-pdf/\">الدليل الكامل لتحويل الصورة إلى PDF</a> و<a href=\"/ar/blog/jpg-ila-pdf-vs-png-ila-pdf/\">JPG مقابل PNG إلى PDF</a>. وإذا كانت صورك بصيغة HEIC، فحوّلها أولًا باستخدام <a href=\"/ar/tahwil-heic-ila-jpg/\">محول HEIC إلى JPG</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل يمكنني تحويل صورة واحدة إلى PDF أم أحتاج إلى عدة صور؟","answer":"يمكنك تحويل صورة واحدة إلى PDF دون مشكلة. صورة واحدة تصبح صفحة واحدة في المستند، وهذا مفيد للنماذج التي تطلب PDF."},{"question":"ماذا يحدث إذا رفعت الصور بترتيب خاطئ؟","answer":"يمكنك إعادة ترتيب الصور في القائمة قبل التوليد. اسحب كل صورة إلى مكانها الصحيح، وتأكد من الترتيب قبل الضغط على زر التوليد."},{"question":"هل يمكنني تحويل الصور إلى PDF على هاتفي؟","answer":"نعم، افتح الأداة في متصفح هاتفك وارفع الصور من معرضك. التحويل يحدث على جهازك، ويمكنك تنزيل PDF مباشرة على هاتفك."},{"question":"هل يحافظ PDF على جودة الصورة الأصلية؟","answer":"نعم، يحافظ PDF على جودة الصور الأصلية حسب إعداد الجودة الذي اخترته. اختر جودة عالية للمستندات المهمة، ومتوازنة للمشاركة اليومية."},{"question":"هل يمكنني حماية ملف PDF الذي أنشئه بكلمة مرور؟","answer":"الأداة الحالية لا تضيف حماية بكلمة مرور. إذا احتجت إلى حماية، فاستخدم أداة PDF مخصصة لإضافة كلمة مرور بعد التوليد."},{"question":"هل يقلل تحويل الصور إلى PDF حجم ملفها؟","answer":"قد يقلل حجم الملف الإجمالي لأن PDF يضغط الصور أثناء التوليد. لكن إذا اخترت جودة عالية، فقد يكون الملف أكبر من الصور منفصلة."}];
